# Example of a test generated by ai-autotest-gen.
# Input: URL github.com/amirzhansar, empty click recording,
# test case "Open the profile. Expected result: the profile name is "Amirzhan"".
import re

from playwright.sync_api import Page, expect


def test_profile_name_is_visible(page: Page) -> None:
    """Open the GitHub profile and check that the displayed name is 'Amirzhan'."""
    page.goto("https://github.com/amirzhansar", wait_until="domcontentloaded")

    expect(page).to_have_url(re.compile(r"github\.com/amirzhansar/?$"))

    # AI-GUESS: locator guessed, it was not in the recording - check it
    profile_name = page.locator("[itemprop='name']")
    expect(profile_name).to_be_visible()
    expect(profile_name).to_contain_text("Amirzhan")
